import java.net.NetworkInterface; public class GetIP { public static void main(String[] args) throws Exception { java.util.Enumeration<NetworkInterface> interfaces = NetworkInterface.getNetworkInterfaces(); while (interfaces.hasMoreElements()) { NetworkInterface iface = interfaces.nextElement(); java.util.Enumeration<java.net.InetAddress> addresses = iface.getInetAddresses(); while (addresses.hasMoreElements()) { java.net.InetAddress addr = addresses.nextElement(); if (!addr.isLoopbackAddress() && !addr.getHostAddress().contains(":")) { System.out.println(addr.getHostAddress()); } } } } }
